python3 -c "
import json,glob,re,collections
bins=['fh','ft','ftts','fsqlite','fmd','fsw','bv','br','ripwire','cass','morph-mcp','morph']
for prof,pat in [('grok','~/.omp/profiles/grok/agent/sessions/-Developer-jev/*.jsonl'),('muse','~/.omp/profiles/muse/agent/sessions/-Developer-jev/*.jsonl'),('default','~/.omp/agent/sessions/-Developer-jev/*.jsonl')]:
    cmds=[]
    for f in glob.glob(pat):
        for line in open(f, errors='replace'):
            try: r=json.loads(line)
            except: continue
            m=r.get('message') or {}
            if m.get('toolName')=='bash' and isinstance(m.get('args'),dict):
                c=(m['args'].get('command') or '')
                if c: cmds.append(c)
    first=collections.Counter(); anyw=collections.Counter()
    for c in cmds:
        toks=re.split(r'[;\n|&]+',c)
        for t in toks:
            t=t.strip()
            t=re.sub(r'^(sudo|sh|bash|env|cd [^;]*;|2>/dev/null|\\\\)\s*','',t)
            m=re.match(r'([a-zA-Z0-9_.\-/]+)',t)
            if m: first[m.group(1).split('/')[-1]]+=1
        for b in bins:
            if re.search(r'(?<![a-zA-Z0-9_.-])'+re.escape(b)+r'(?![a-zA-Z0-9_.-])',c): anyw[b]+=1
    print(prof,'ncmd=',len(cmds))
    print(' first:',dict(first.most_common(15)))
    print(' anyword:',{b:anyw[b] for b in bins if anyw[b]})
"

